select
  id, reminder_task_id, tip_type, msg_tip_template, phone_tip_template, replay_time, interval_time, interval_unit, create_time, update_time
from msg_reminder_task_template


        and id = #{id}


        and reminder_task_id = #{reminderTaskId}


        and tip_type = #{tipType}


        and msg_tip_template = #{msgTipTemplate}


        and phone_tip_template = #{phoneTipTemplate}


        and replay_time = #{replayTime}


        and interval_time = #{intervalTime}


        and interval_unit = #{intervalUnit}


        and create_time = #{createTime}


        and update_time = #{updateTime}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from msg_reminder_task_template


        and id = #{id}


        and reminder_task_id = #{reminderTaskId}


        and tip_type = #{tipType}


        and msg_tip_template = #{msgTipTemplate}


        and phone_tip_template = #{phoneTipTemplate}


        and replay_time = #{replayTime}


        and interval_time = #{intervalTime}


        and interval_unit = #{intervalUnit}


        and create_time = #{createTime}


        and update_time = #{updateTime}
